import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

export interface AppearanceSettings {
  theme: 'light' | 'dark' | 'system';
  scale: number;
  dense: boolean;
  font: string;
}

const themeItems = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const themeLabels: Record<AppearanceSettings['theme'], string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const fontOptions = [
  { value: 'sans', label: 'Inter Tight', meta: 'по умолчанию' },
  { value: 'display', label: 'Fraunces' },
  { value: 'mono', label: 'JetBrains Mono' },
];

function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    theme: 'system',
    scale: 100,
    dense: false,
    font: 'sans',
    ...defaultValue,
  });

  const update = (patch: Partial<AppearanceSettings>) => {
    setSettings((current) => {
      const next = { ...current, ...patch };
      onChange?.(next);
      return next;
    });
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <header style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {themeLabels[settings.theme]}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <span style={{ color: 'var(--jx-text-2)', fontSize: '14px' }}>Тема</span>
        <JxToggle
          items={themeItems}
          value={settings.theme}
          onValueChange={(value) =>
            update({ theme: value as AppearanceSettings['theme'] })
          }
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(value) => update({ scale: value })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => update({ dense: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        placeholder="Выберите шрифт"
        options={fontOptions}
        value={settings.font}
        onValueChange={(value) => update({ font: value })}
      />
    </section>
  );
}

export default AppearanceSettingsScreen;

